const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], m = tok[1];
const dist = new Array(n + 1).fill(Infinity);
dist[1] = 0;
let negative = true;
for (let round = 0; round < n; round++) {
  let changed = false;
  for (let i = 0; i < m; i++) {
    const a = tok[2 + 3 * i], b = tok[3 + 3 * i], w = tok[4 + 3 * i];
    if (dist[a] !== Infinity && dist[a] + w < dist[b]) { dist[b] = dist[a] + w; changed = true; }
  }
  if (!changed) { negative = false; break; }
}
console.log(negative ? "YES" : "NO");

solutions.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), m = sc.nextInt();
        int[] ea = new int[m], eb = new int[m];
        long[] ew = new long[m];
        for (int i = 0; i < m; i++) {
            ea[i] = sc.nextInt();
            eb[i] = sc.nextInt();
            ew[i] = sc.nextLong();
        }
        long INF = Long.MAX_VALUE / 4;
        long[] dist = new long[n + 1];
        Arrays.fill(dist, INF);
        dist[1] = 0;
        boolean negative = true;
        for (int round = 0; round < n; round++) {
            boolean changed = false;
            for (int i = 0; i < m; i++) {
                if (dist[ea[i]] != INF && dist[ea[i]] + ew[i] < dist[eb[i]]) {
                    dist[eb[i]] = dist[ea[i]] + ew[i];
                    changed = true;
                }
            }
            if (!changed) { negative = false; break; }
        }
        System.out.println(negative ? "YES" : "NO");
    }
}

